// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v, uint _decimals) public {
        // Restrict to admissible domain: non-empty _tos array and _decimals not too large to prevent overflow
        vm.assume(_tos.length > 0);
        vm.assume(_decimals <= 77); // keep multiplication safe from overflow on uint scaling
        // Ensure the external call to caddress succeeds by using a fresh contract that actually accepts the call
        // We deploy a minimal helper that always succeeds on the targeted selector
        Succesor helper = new Succesor();
        // Use helper address as the caddress argument
        // Bind v to avoid overflow in v * 10 ** _decimals
        v = bound(v, 0, type(uint256).max / (10 ** _decimals));
        // The transfer call must not revert; we can assume it succeeds for the assertion.
        // We use try/catch to capture return value
        bool ret;
        try c.transfer(from, address(helper), _tos, v, _decimals) returns (bool result) {
            ret = result;
        } catch {
            // If it reverts, we skip this fuzz run because the property only applies when it completes
            vm.assume(false);
        }
        assertTrue(ret);
    }
}

contract Succesor {
    fallback() external payable { }
}
